create extension if not exists pgcrypto;
create type public.platform_role as enum ('user','superadmin');
create type public.member_role as enum ('owner','admin','manager','seller','viewer');
create type public.sale_status as enum ('paid','voided','refunded');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, platform_role public.platform_role not null default 'user', created_at timestamptz not null default now());
create table public.businesses (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, status text not null default 'active', timezone text not null default 'America/Bogota', description text, logo_url text, phone text, address text, city text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.business_members (business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.member_role not null, active boolean not null default true, created_at timestamptz not null default now(), primary key (business_id,user_id));
create table public.categories (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, description text, created_at timestamptz not null default now(), unique(business_id,name));
create table public.products (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, category_id uuid references public.categories(id) on delete set null, name text not null, description text, reference text, sku text, material text, price numeric(14,2) not null default 0 check(price >= 0), stock integer not null default 0 check(stock >= 0), low_stock_threshold integer not null default 2 check(low_stock_threshold >= 0), available boolean not null default true, image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,sku));
create table public.customers (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, email text, phone text, notes text, created_at timestamptz not null default now());
create table public.sales (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, customer_id uuid references public.customers(id) on delete set null, total numeric(14,2) not null check(total >= 0), status public.sale_status not null default 'paid', created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.sale_items (id uuid primary key default gen_random_uuid(), sale_id uuid not null references public.sales(id) on delete cascade, product_id uuid not null references public.products(id), quantity integer not null check(quantity > 0), unit_price numeric(14,2) not null check(unit_price >= 0));
create table public.inventory_movements (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, quantity integer not null check(quantity <> 0), movement_type text not null check(movement_type in ('entry','sale','adjustment','return')), reason text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.business_settings (business_id uuid primary key references public.businesses(id) on delete cascade, catalog_enabled boolean not null default true, low_stock_alerts boolean not null default true, currency text not null default 'COP', updated_at timestamptz not null default now());
create index products_business_stock_idx on public.products(business_id,stock); create index movements_business_created_idx on public.inventory_movements(business_id,created_at desc); create index sales_business_created_idx on public.sales(business_id,created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id) values(new.id) on conflict do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.apply_inventory_movement() returns trigger language plpgsql security definer set search_path = public as $$ begin update public.products set stock = stock + new.quantity, updated_at = now() where id = new.product_id and business_id = new.business_id; if not found then raise exception 'Producto no pertenece al negocio'; end if; return new; end; $$;
create trigger inventory_movement_apply after insert on public.inventory_movements for each row execute procedure public.apply_inventory_movement();
create or replace function public.is_business_member(target uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.business_members where business_id=target and user_id=auth.uid() and active); $$;
create or replace function public.can_write_business(target uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.business_members where business_id=target and user_id=auth.uid() and active and role in ('owner','admin','manager','seller')); $$;
